draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw excess
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 4, H / 2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 4, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Excess', W / 4, H / 2);

  // draw deficiency
  ctx.beginPath();
  ctx.arc(W - W / 4, H / 2, 20 + 20 * Math.sin(t + Math.PI), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W - W / 4, H / 2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fillText('Deficiency', W - W / 4, H / 2);

  // draw mean
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 30 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '30px Arial';
  ctx.fillText('Mean', W / 2, H / 2);

  ctx.restore();
}
